# -*- coding: utf-8 -*-
# Тренажёр «Выбор маршрута», проверочные вопросы, тест и финал.
from _rt_lib import *
from _rt_s1 import N, CL, E, T, PT, draw, pkt, on, off, add, rm, hl, scan, txt

# ================================================================ Тренажёр «Выбор маршрута»
TR_ROWS = [("C", "192.168.1.0/24", "напрямую", "gi1/0/1", "LAN"), ("S", "10.0.0.0/8", "172.16.12.2", "gi1/0/2", "R2"),
           ("S", "10.20.0.0/16", "172.16.13.2", "gi1/0/3", "R3"), ("S", "10.20.30.0/24", "172.16.14.2", "gi1/0/4", "R4"),
           ("S", "172.20.0.0/16", "172.16.13.2", "gi1/0/3", "R3"), ("S", "0.0.0.0/0", "172.16.15.2", "gi1/0/5", "R5")]
topo("ttr", {"vb": [760, 470], "al": "R1 и соседние маршрутизаторы R2–R5, локальная сеть 192.168.1.0/24", "nohint": 1,
             "n": [CL("LAN", 95, 235, 170, 100, "LAN", l2="192.168.1.0/24"), N("R1", "r", 330, 235, "R1", "b"), N("R2", "r", 560, 70, "R2", "r"),
                   N("R3", "r", 650, 205, "R3", "r"), N("R4", "r", 610, 345, "R4", "r"), N("R5", "r", 360, 420, "R5", "r"),
                   CL("NET2", 560, 20, 130, 44, "10.0.0.0/8", z=13), CL("NET4", 700, 420, 150, 44, "10.20.30.0/24", z=13)],
             "e": [E("LAN", "R1"), E("R1", "R2"), E("R1", "R3"), E("R1", "R4"), E("R1", "R5")],
             "tx": [T(470, 140, ".12.2", "g", z=13), T(500, 212, ".13.2", "g", z=13), T(480, 300, ".14.2", "g", z=13), T(318, 340, ".15.2", "g", "end", 13),
                    T(360, 462, "Интернет (по умолчанию)", "dm", z=13), T(700, 245, "10.20.0.0/16, 172.20.0.0/16", "dm", "end", 12)],
             "p": [PT("LAN", ["R1", "LAN"]), PT("R2", ["R1", "R2"]), PT("R3", ["R1", "R3"]), PT("R4", ["R1", "R4"]), PT("R5", ["R1", "R5"])], "pk": []})
trt = table("Таблица маршрутизации R1", ["Код", "Сеть назначения", "Следующий переход", "Интерфейс"], [list(r[:4]) for r in TR_ROWS], tid="trt")
slide("Тренажёр: выбор маршрута", head("Тренажёр: выбор маршрута", "Введите адрес назначения или найдите строку сами — правило самого длинного совпадения", small=True) +
      f'''<div class="two top trn" id="trn"><div class="col"><div class="topo" data-s="1" data-topo="ttr"></div></div>
<div class="col">{trt}
<div class="pn" data-s="1"><div class="row"><button type="button" class="btn on" data-m="show">Показать решение</button><button type="button" class="btn" data-m="self">Сам найди строку</button></div>
<div class="row" style="margin-top:.6rem"><label for="trip">IP назначения</label><input id="trip" value="10.20.30.77" inputmode="decimal" autocomplete="off" spellcheck="false">
<button type="button" class="btn" id="trgo">Проверить</button><button type="button" class="btn" id="trnew">Другое условие</button></div>
<div class="msg" id="trmsg" aria-live="polite"></div></div></div></div>''')

# ================================================================ Проверь себя
slide("Проверь себя: 1", head("Проверь себя", "Нажмите на вопрос, чтобы увидеть ответ") + grid(
    qa("Чем маршрут с прямым подключением отличается от удалённого?", "Прямой маршрут появляется автоматически, когда интерфейс настроен и в состоянии up/up; следующего перехода у него нет. Удалённый ведёт к сети за другим маршрутизатором и задаётся статически или протоколом динамической маршрутизации."),
    qa("Что сделает маршрутизатор, если подходящего маршрута нет?", "Проверит маршрут по умолчанию 0.0.0.0/0. Если его нет — пакет отбрасывается."),
    qa("В таблице есть 172.16.0.0/12, 172.16.0.0/18 и 172.16.0.0/26. Куда уйдёт пакет для 172.16.0.10?", "По 172.16.0.0/26: это самое длинное совпадение."),
    qa("Статический маршрут и RIP ведут в одну сеть с одинаковой маской. Какой попадёт в таблицу?", "Статический: у него preference 1, у RIP — 100. Меньшее значение — выше приоритет."),
    qa("Как RIP и OSPF считают метрику?", "RIP — количество переходов (максимум 15, 16 — недоступно). OSPF — сумма стоимостей интерфейсов с учётом полосы пропускания."),
    qa("Что меняется в кадре при прохождении маршрутизатора, а что нет?", "Меняются MAC-адреса источника и назначения (новая инкапсуляция), уменьшается TTL. IP-адреса источника и назначения остаются прежними."),
    cols="repeat(2,minmax(0,1fr))"))

slide("Проверь себя: 2", head("Проверь себя", "Команды и термины") + grid(
    qa("Чем RIB отличается от FIB?", "RIB хранит все маршруты из всех источников, в том числе несколько к одной сети (show ip route all). FIB — только лучшие маршруты; по ней и пересылаются пакеты (show ip route)."),
    qa("Что такое плавающий статический маршрут?", "Резервный статический маршрут с большей метрикой (например, 10). Он становится активным, только когда основной недоступен."),
    qa("Что означает запись [1/10] в выводе show ip route?", "1 — preference источника маршрута, 10 — стоимость (cost)."),
    qa("Что такое рекурсивный поиск?", "Если в маршруте указан только адрес следующего перехода, маршрутизатор повторно ищет в таблице маршрут к этому адресу, чтобы определить выходной интерфейс."),
    qa("Как настроить маршрут к 192.168.20.0/24 через 203.0.113.2 на ESR?", "<c>R1(config)# ip route 192.168.20.0/24 203.0.113.2</c>"),
    qa("Почему родительский маршрут 1-го уровня не бывает окончательным?", "В нём нет следующего перехода или выходного интерфейса: он только объединяет дочерние подсети классового адреса."),
    cols="repeat(2,minmax(0,1fr))"))

slide("Проверь себя: 3", head("Проверь себя", "Путь пакета и маршрутизация между VLAN") + grid(
    qa("Что происходит с TTL на каждом маршрутизаторе и зачем это нужно?", "TTL уменьшается на единицу; при нуле пакет отбрасывается, а отправителю уходит уведомление. Так пакет не может вечно крутиться в петле маршрутизации. Контрольная сумма при этом пересчитывается."),
    qa("Почему при передаче по каналу PPP маршрутизатор не отправляет ARP-запрос?", "В кадре PPP MAC-адреса не используются, поэтому преобразовывать IP-адрес следующего перехода в MAC-адрес не нужно."),
    qa("Что делает ПК перед отправкой пакета, чтобы понять, нужен ли ему шлюз?", "Выполняет операцию AND своего IP-адреса с маской и то же самое с IP-адресом назначения. Совпали подсети — отправляет напрямую через ARP, не совпали — на шлюз по умолчанию."),
    qa("Почему обычный интерфейс маршрутизатора отбрасывает кадр с меткой 802.1Q?", "Метка увеличивает стандартный заголовок Ethernet на 32 бита, и маршрутизатор считает декапсулированный кадр бракованным."),
    qa("Чем Router-on-a-Stick отличается от традиционного метода?", "В традиционном методе на каждую VLAN нужен отдельный физический интерфейс L3, а порт коммутатора работает в режиме access. В ROAS используется один физический интерфейс с подинтерфейсами, а порт коммутатора — транк."),
    qa("Что такое SVI и когда он переходит в состояние UP/UP?", "Switch Virtual Interface — виртуальный интерфейс коммутатора, создаваемый вместе с VLAN и выступающий шлюзом для неё. Он поднимается, когда в этой VLAN есть хотя бы один включённый порт доступа или транковый порт."),
    cols="repeat(2,minmax(0,1fr))"))

